1	// Package node defines the document data model shared by every format
2	// decoder/encoder and the expression evaluator. It mirrors the shape of a
3	// YAML node tree: every JSON/XML/CSV/... document is decoded into this tree,
4	// and every encoder renders from it.
5	package node
6	
7	// Kind identifies the structural kind of a Node.
8	type Kind int
9	
10	const (
11		DocumentKind Kind = 1 + iota
12		SequenceKind
13		MappingKind
14		ScalarKind
15		AliasKind
16	)
17	
18	func (k Kind) String() string {
19		switch k {
20		case DocumentKind:
21			return "Document"
22		case SequenceKind:
23			return "Sequence"
24		case MappingKind:
25			return "Mapping"
26		case ScalarKind:
27			return "Scalar"
28		case AliasKind:
29			return "Alias"
30		}
31		return "Unknown"
32	}
33	
34	// Style is a bitmask of presentation styles (only meaningful for output).
35	type Style int
36	
37	const (
38		StyleDefault       Style = 0
39		TaggedStyle        Style = 1 << 0
40		DoubleQuotedStyle  Style = 1 << 1
41		SingleQuotedStyle  Style = 1 << 2
42		LiteralStyle       Style = 1 << 3
43		FoldedStyle        Style = 1 << 4
44		FlowStyle          Style = 1 << 5
45	)
46	
47	func (s Style) IsFlow() bool          { return s&FlowStyle != 0 }
48	func (s Style) IsDoubleQuoted() bool  { return s&DoubleQuotedStyle != 0 }
49	func (s Style) IsSingleQuoted() bool  { return s&SingleQuotedStyle != 0 }
50	func (s Style) IsLiteral() bool       { return s&LiteralStyle != 0 }
51	func (s Style) IsFolded() bool        { return s&FoldedStyle != 0 }
52	func (s Style) IsTagged() bool        { return s&TaggedStyle != 0 }
53	func (s Style) IsQuoted() bool {
54		return s&(DoubleQuotedStyle|SingleQuotedStyle) != 0
55	}
56	
57	// Node is a single node in a document tree.
58	//
59	// For MappingKind, Content holds alternating key/value nodes
60	// (key at even indexes, value at odd indexes).
61	// For SequenceKind, Content holds the elements.
62	// For DocumentKind, Content holds exactly one root node (or zero for an
63	// empty document).
64	// For ScalarKind, Value holds the text and Tag the resolved YAML tag
65	// (e.g. "!!str", "!!int", "!!float", "!!bool", "!!null", "!!timestamp").
66	// For AliasKind, Alias points to the anchored node it refers to and Value
67	// holds the alias name.
68	type Node struct {
69		Kind    Kind
70		Style   Style
71		Tag     string
72		Value   string
73		Anchor  string
74		Alias   *Node
75		Content []*Node
76	
77		HeadComment string
78		LineComment string
79		FootComment string
80	}
81	
82	// NewScalar creates a scalar node with the given tag and value.
83	func NewScalar(tag, value string) *Node {
84		return &Node{Kind: ScalarKind, Tag: tag, Value: value}
85	}
86	
87	// NewString creates a !!str scalar.
88	func NewString(value string) *Node { return NewScalar("!!str", value) }
89	
90	// NewNull creates a !!null scalar with value "null".
91	func NewNull() *Node { return NewScalar("!!null", "null") }
92	
93	// NewMapping creates an empty !!map node.
94	func NewMapping() *Node { return &Node{Kind: MappingKind, Tag: "!!map"} }
95	
96	// NewSequence creates an empty !!seq node.
97	func NewSequence() *Node { return &Node{Kind: SequenceKind, Tag: "!!seq"} }
98	
99	// NewDocument wraps a root node in a document node.
100	func NewDocument(root *Node) *Node {
101		d := &Node{Kind: DocumentKind}
102		if root != nil {
103			d.Content = []*Node{root}
104		}
105		return d
106	}
107	
108	// Root returns the root content node of a document (nil if empty).
109	func (n *Node) Root() *Node {
110		if n.Kind == DocumentKind {
111			if len(n.Content) == 0 {
112				return nil
113			}
114			return n.Content[0]
115		}
116		return n
117	}
118	
119	// MapKeys returns the key nodes of a mapping.
120	func (n *Node) MapKeys() []*Node {
121		keys := make([]*Node, 0, len(n.Content)/2)
122		for i := 0; i+1 < len(n.Content); i += 2 {
123			keys = append(keys, n.Content[i])
124		}
125		return keys
126	}
127	
128	// MapValue returns the value node for a key in a mapping, or nil.
129	func (n *Node) MapValue(key string) *Node {
130		if n.Kind == DocumentKind {
131			return n.Root().MapValue(key)
132		}
133		if n == nil || n.Kind != MappingKind {
134			return nil
135		}
136		for i := 0; i+1 < len(n.Content); i += 2 {
137			if n.Content[i].Value == key {
138				return n.Content[i+1]
139			}
140		}
141		return nil
142	}
143	
144	// MapSet sets (or appends) a key/value pair in a mapping.
145	func (n *Node) MapSet(key *Node, value *Node) {
146		for i := 0; i+1 < len(n.Content); i += 2 {
147			if n.Content[i].Value == key.Value {
148				n.Content[i+1] = value
149				return
150			}
151		}
152		n.Content = append(n.Content, key, value)
153	}
154	
155	// IsNull reports whether the node is a !!null scalar.
156	func (n *Node) IsNull() bool {
157		return n != nil && n.Kind == ScalarKind && n.Tag == "!!null"
158	}
159	
160	// Clone makes a deep copy of the node (alias targets are shared).
161	func (n *Node) Clone() *Node {
162		if n == nil {
163			return nil
164		}
165		c := *n
166		if n.Content != nil {
167			c.Content = make([]*Node, len(n.Content))
168			for i, ch := range n.Content {
169				c.Content[i] = ch.Clone()
170			}
171		}
172		return &c
173	}
174	
175	// AddFootComment appends a line to the foot comment.
176	func (n *Node) AddFootComment(s string) {
177		if n.FootComment == "" {
178			n.FootComment = s
179		} else {
180			n.FootComment = n.FootComment + "\n" + s
181		}
182	}
183	
184	// AddHeadComment appends a line to the head comment.
185	func (n *Node) AddHeadComment(s string) {
186		if n.HeadComment == "" {
187			n.HeadComment = s
188		} else {
189			n.HeadComment = n.HeadComment + "\n" + s
190		}
191	}

